// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 t1, uint256 t2) public {
        // Keep timestamps in a wide, realistic domain (must fit uint64 for vm.warp)
        t1 = bound(t1, 1, type(uint64).max / 2);
        t2 = bound(t2, 1, type(uint64).max / 2);
        uint256 hi = t1 >= t2 ? t1 : t2;
        uint256 lo = t1 >= t2 ? t2 : t1;

        vm.deal(address(this), 20 ether);

        // First call at the later (or equal) timestamp
        vm.warp(hi);
        (bool ok1, ) = address(c).call{value: 10 ether}("");
        assertTrue(ok1); // admissible: exact 10 ether, timestamp > pastBlockTime (0)
        assertEq(c.pastBlockTime(), hi);

        // Second call at the earlier timestamp: must revert if lo < hi
        vm.warp(lo);
        (bool ok2, ) = address(c).call{value: 10 ether}("");

        // General rule: pastBlockTime NEVER decreases; it always equals the
        // latest timestamp the contract has accepted, i.e. hi.
        // The reference C satisfies this for every admissible input:
        //   - if lo > hi: impossible (hi is the max)
        //   - if lo == hi: call reverts, pastBlockTime stays hi
        //   - if lo < hi: timestamp check reverts the call, pastBlockTime stays hi
        // The mutant (check deleted) accepts the second call at lo < hi and
        // overwrites pastBlockTime with lo < hi, breaking the rule.
        assertTrue(c.pastBlockTime() == hi, "pastBlockTime must never decrease");
    }
}
